    Polynomial.mul_coeff_zero,Polynomial.coeff_C,Polynomial.coeff_X,
    Polynomial.coeff_one,zero_ne_one,one_ne_zero,if_false,if_true,
    mul_zero,zero_mul,add_zero,zero_add,mul_one,one_mul,hp,hq]
